231	  /** Counts the bytes in the given input stream using skip if possible. */
232	  private static long countBySkipping(InputStream in) throws IOException {
233	    long count = 0;
234	    long skipped;
235	    while ((skipped = skipUpTo(in, Integer.MAX_VALUE)) > 0) {
236	      count += skipped;
