447	  /**
448	   * Concatenates multiple {@link CharSource} instances into a single source. Streams returned from
449	   * the source will contain the concatenated data from the streams of the underlying sources.
450	   *
451	   * <p>Only one underlying stream will be open at a time. Closing the concatenated stream will
452	   * close the open underlying stream.
453	   *
454	   * <p>Note: The input {@code Iterator} will be copied to an {@code ImmutableList} when this method
455	   * is called. This will fail if the iterator is infinite and may cause problems if the iterator
456	   * eagerly fetches data for each source when iterated (rather than producing sources that only
457	   * load data through their streams). Prefer using the {@link #concat(Iterable)} overload if
458	   * possible.
459	   *
460	   * @param sources the sources to concatenate
461	   * @return a {@code CharSource} containing the concatenated data
462	   * @throws NullPointerException if any of {@code sources} is {@code null}
463	   * @since 15.0
464	   */
465	  public static CharSource concat(Iterator<? extends CharSource> sources) {
466	    return concat(ImmutableList.copyOf(sources));
467	  }
468	
469	  /**
470	   * Concatenates multiple {@link CharSource} instances into a single source. Streams returned from
471	   * the source will contain the concatenated data from the streams of the underlying sources.
472	   *
473	   * <p>Only one underlying stream will be open at a time. Closing the concatenated stream will
474	   * close the open underlying stream.
475	   *
476	   * @param sources the sources to concatenate
477	   * @return a {@code CharSource} containing the concatenated data
478	   * @throws NullPointerException if any of {@code sources} is {@code null}
479	   * @since 15.0
480	   */
481	  public static CharSource concat(CharSource... sources) {
482	    return concat(ImmutableList.copyOf(sources));
483	  }
484	
485	  /**
486	   * Returns a view of the given character sequence as a {@link CharSource}. The behavior of the
487	   * returned {@code CharSource} and any {@code Reader} instances created by it is unspecified if
488	   * the {@code charSequence} is mutated while it is being read, so don't do that.
489	   *
490	   * @since 15.0 (since 14.0 as {@code CharStreams.asCharSource(String)})
491	   */
