493	    return charSequence instanceof String
494	        ? new StringCharSource((String) charSequence)
495	        : new CharSequenceCharSource(charSequence);
496	  }
497	
498	  /**
499	   * Returns an immutable {@link CharSource} that contains no characters.
500	   *
501	   * @since 15.0
502	   */
503	  public static CharSource empty() {
504	    return EmptyCharSource.INSTANCE;
505	  }
