507	  /** A byte source that reads chars from this source and encodes them as bytes using a charset. */
508	  private final class AsByteSource extends ByteSource {
509	
510	    final Charset charset;
511	
512	    AsByteSource(Charset charset) {
513	      this.charset = checkNotNull(charset);
514	    }
515	
516	    @Override
517	    public CharSource asCharSource(Charset charset) {
518	      if (charset.equals(this.charset)) {
519	        return CharSource.this;
520	      }
521	      return super.asCharSource(charset);
522	    }
523	
524	    @Override
525	    public InputStream openStream() throws IOException {
526	      return new ReaderInputStream(CharSource.this.openStream(), charset, 8192);
527	    }
528	
529	    @Override
530	    public String toString() {
531	      return CharSource.this.toString() + ".asByteSource(" + charset + ")";
532	    }
533	  }
534	
535	  private static class CharSequenceCharSource extends CharSource {
536	
537	    private static final Splitter LINE_SPLITTER = Splitter.onPattern("\r\n|\n|\r");
538	
539	    final CharSequence seq;
540	
541	    CharSequenceCharSource(CharSequence seq) {
542	      this.seq = checkNotNull(seq);
543	    }
544	
545	    @Override
546	    public Reader openStream() {
547	      return new CharSequenceReader(seq);
548	    }
549	
550	    @Override
551	    public String read() {
552	      return seq.toString();
553	    }
554	
555	    @Override
556	    public boolean isEmpty() {
557	      return seq.length() == 0;
558	    }
559	
560	    @Override
561	    public long length() {
562	      return seq.length();
563	    }
564	
565	    @Override
566	    public Optional<Long> lengthIfKnown() {
567	      return Optional.of((long) seq.length());
568	    }
569	
570	    /**
571	     * Returns an iterator over the lines in the string. If the string ends in a newline, a final
572	     * empty string is not included, to match the behavior of BufferedReader/LineReader.readLine().
573	     */
574	    private Iterator<String> linesIterator() {
575	      return new AbstractIterator<String>() {
576	        final Iterator<String> lines = LINE_SPLITTER.split(seq).iterator();
577	
578	        @Override
579	        protected @Nullable String computeNext() {
580	          if (lines.hasNext()) {
581	            String next = lines.next();
582	            // skip last line if it's empty
583	            if (lines.hasNext() || !next.isEmpty()) {
584	              return next;
585	            }
586	          }
587	          return endOfData();
588	        }
589	      };
590	    }
591	
592	    @Override
593	    public Stream<String> lines() {
594	      return stream(linesIterator());
595	    }
596	
597	    @Override
598	    public @Nullable String readFirstLine() {
599	      Iterator<String> lines = linesIterator();
600	      return lines.hasNext() ? lines.next() : null;
601	    }
602	
603	    @Override
604	    public ImmutableList<String> readLines() {
605	      return ImmutableList.copyOf(linesIterator());
606	    }
607	
608	    @Override
609	    @ParametricNullness
610	    public <T extends @Nullable Object> T readLines(LineProcessor<T> processor) throws IOException {
611	      Iterator<String> lines = linesIterator();
612	      while (lines.hasNext()) {
613	        if (!processor.processLine(lines.next())) {
614	          break;
615	        }
616	      }
617	      return processor.getResult();
618	    }
619	
620	    @Override
621	    public String toString() {
622	      return "CharSource.wrap(" + Ascii.truncate(seq, 30, "...") + ")";
623	    }
624	  }
625	
626	  /**
627	   * Subclass specialized for string instances.
628	   *
629	   * <p>Since Strings are immutable and built into the jdk we can optimize some operations
630	   *
631	   * <ul>
632	   *   <li>use {@link StringReader} instead of {@link CharSequenceReader}. It is faster since it can
633	   *       use {@link String#getChars(int, int, char[], int)} instead of copying characters one by
634	   *       one with {@link CharSequence#charAt(int)}.
635	   *   <li>use {@link Appendable#append(CharSequence)} in {@link #copyTo(Appendable)} and {@link
636	   *       #copyTo(CharSink)}. We know this is correct since strings are immutable and so the length
637	   *       can't change, and it is faster because many writers and appendables are optimized for
638	   *       appending string instances.
639	   * </ul>
640	   */
641	  private static class StringCharSource extends CharSequenceCharSource {
642	    StringCharSource(String seq) {
643	      super(seq);
644	    }
645	
646	    @Override
647	    public Reader openStream() {
648	      return new StringReader((String) seq);
649	    }
650	
651	    @Override
652	    public long copyTo(Appendable appendable) throws IOException {
653	      appendable.append(seq);
654	      return seq.length();
655	    }
656	
657	    @Override
658	    public long copyTo(CharSink sink) throws IOException {
659	      checkNotNull(sink);
660	      Closer closer = Closer.create();
661	      try {
662	        Writer writer = closer.register(sink.openStream());
663	        writer.write((String) seq);
664	        return seq.length();
665	      } catch (Throwable e) {
666	        throw closer.rethrow(e);
667	      } finally {
668	        closer.close();
669	      }
670	    }
671	  }
672	
673	  private static final class EmptyCharSource extends StringCharSource {
674	
675	    private static final EmptyCharSource INSTANCE = new EmptyCharSource();
676	
677	    private EmptyCharSource() {
678	      super("");
679	    }
680	
681	    @Override
682	    public String toString() {
683	      return "CharSource.empty()";
684	    }
685	  }
